            const __end_6 = store.weak_refs.count;
            while (i < __end_6) : (i += 1) {
                const item_ref = store.weak_refs.peekItem(i);
                if ((item_ref.key() == key)) {
                    return WeakRefLocation{ .index = i, .@"ref" = item_ref };
                }
            }
        }
        return null;
}

pub fn sweepWeakRefs(self: SourceMapStore, timer: *EventLoopTimer, now_ts: *const bun.timespec) void {
    _ = &self;
        _ = mapLog("sweepWeakRefs", &.{});
        const store: *Self = @fieldParentPtr("weak_ref_sweep_timer", timer);
        _ = assert((store.owner().magic == .valid));
        const now: u64 = @max(now_ts.sec, 0);
        defer {
        _ = store.owner().emitMemoryVisualizerMessageIfNeeded();
        }
        while (store.weak_refs.readItem()) |item| {
            if ((item.expire <= now)) {
                _ = store.unrefCount(item.key(), item.count);
            } else {
                _ = ((store.weak_refs.unget((&.{ item }))) catch unreachable);
                store.weak_ref_sweep_timer.state = .FIRED;
                const next_ts = Timespec{ .sec = (item.expire + 1), .nsec = 0 };
                _ = store.owner().vm.timer.update((&store.weak_ref_sweep_timer), (&next_ts));
                return;
            }
        }
        store.weak_ref_sweep_timer.state = .CANCELLED;
}

pub fn getParsedSourceMap(self: SourceMapStore, store: *Self, script_id: Key, arena_alloc: Allocator, gpa: Allocator) ?GetResult {
    _ = &self;
        const index = ((store.entries.getIndex(script_id)) orelse { return null; });
        const entry = (&store.entries.values()[@as(usize, @intCast(index))]);
        const script_id_decoded: SourceId = @bitCast(script_id.get());
        const vlq_bytes = bun.handleOom(entry.renderMappings(script_id_decoded.kind, arena_alloc, arena_alloc));
        switch (SourceMap.Mapping.parse(gpa, vlq_bytes, null, @intCast(entry.paths.len), 0, .{})) {
.fail => |fail| {
_ = Output.debugWarn("Failed to re-parse source map: {s}", .{ fail.msg });
        return null;
},
.success => |psm| {
return StoreGetResult{ .index = bun.GenericIndex(u32, StoreEntry).init(@intCast(index)), .mappings = psm.mappings, .file_paths = entry.paths, .entry_files = (&entry.files) };
},
}
}
const Self = @This();
pub const Key = bun.GenericIndex(u64, .{ "Key of", Self });
pub const empty = empty_source_map_store;
pub const SourceId = StoreSourceId;
pub const Entry = StoreEntry;
pub const WeakRef = StoreWeakRef;
pub const GetResult = StoreGetResult;
